    func testAPIErrorCarriesEverythingTheServerSent() async {
        let body = #"{"type":"error","error":{"type":"invalid_request_error","code":"validation_failed","message":"Поле не заполнено","fields":[{"code":"too_small","message":"нужно","path":"title"}],"resets_at":"2026-12-01"},"request_id":"req_body_9"}"#
        server.enqueue(.json(400, body, headers: ["X-Request-Id": "req_header", "X-RateLimit-Remaining": "0"]))
        await assertThrows(try await makeClient().chat.update(id: "d1", body: ChatDialogPatch(title: ""))) { error in
            guard let api = error as? APIError else { return XCTFail("\(error)") }
            XCTAssertEqual(api.statusCode, 400)
            XCTAssertEqual(api.kind, .invalidRequest)
            XCTAssertEqual(api.type, "invalid_request_error")
            XCTAssertEqual(api.code, "validation_failed")
            XCTAssertEqual(api.serverMessage, "Поле не заполнено")
            XCTAssertEqual(api.requestID, "req_body_9")
            XCTAssertEqual(api.fields.first?.path, "title")
            XCTAssertEqual(api.fields.first?.code, .tooSmall)
            XCTAssertEqual(api.extra["resets_at"], .string("2026-12-01"))
            XCTAssertEqual(api.rateLimit?.remaining, 0)
            XCTAssertTrue(api.isEnvelope)
            XCTAssertNotNil(api.detail)
            // The server message reaches any standard error UI.
            XCTAssertTrue(error.localizedDescription.contains("Поле не заполнено"), error.localizedDescription)
            XCTAssertTrue("\(error)".contains("req_body_9"))
            XCTAssertTrue(error is any TungoError)
        }
    }

