    func testRetryAfterHeaderForms() async throws {
        let forms: [([String: String], TimeInterval)] = [
            (["Retry-After": "2"], 2), (["retry-after-ms": "1500"], 1.5),
            (["retry-after-ms": "250", "Retry-After": "9"], 0.25), (["Retry-After": "nonsense"], 0.5),
            // Zero, a negative number and a date in the past are not an order to retry at once:
            // the computed backoff (0.5 s for the first retry) applies.
            (["Retry-After": "0"], 0.5), (["retry-after-ms": "0"], 0.5), (["Retry-After": "-3"], 0.5),
            (["Retry-After": "Mon, 09 Nov 2020 15:00:07 GMT"], 0.5),
        ]
        for (headers, expected) in forms {
            let recorder = SleepRecorder()
            server.enqueue(.json(429, "{}", headers: headers), .json(200, Fixture.dialogList))
            _ = try await makeClient(recorder: recorder).chat.list()
            XCTAssertEqual(recorder.delays, [expected], "\(headers)")
        }
    }

    func testRetryAfterAsAnHTTPDate() {
        let now = Date(timeIntervalSince1970: 1794236400)
        var headers = HTTPHeaders()
        headers["Retry-After"] = "Mon, 09 Nov 2026 15:00:07 GMT"
        let delay = RetryPolicy.retryAfter(headers: headers, now: now)
        XCTAssertEqual(delay ?? -1, 7, accuracy: 0.001)
        XCTAssertEqual(APIError.make(statusCode: 429, headers: headers, body: Data(), now: now).retryAfter ?? -1, 7, accuracy: 0.001)
    }

