    func testCustomTransportReceivesTheRequest() async throws {
        final class Canned: TungoTransport, @unchecked Sendable {
            let lock = NSLock()
            var seen: [TungoHTTPRequest] = []
            func send(_ request: TungoHTTPRequest) async throws -> TungoHTTPResponse {
                lock.locked { seen.append(request) }
                return TungoHTTPResponse(statusCode: 200, headers: HTTPHeaders(["Content-Type": "application/json"]), data: Data(Fixture.dialogList.utf8))
            }
        }
        let transport = Canned()
        let client = TungoClient(apiKey: "k", baseURL: URL(string: "https://example.invalid/api/"), companyID: "co_1", transport: transport, environment: [:])
        let page = try await client.chat.list(limit: 1)
        XCTAssertEqual(page.data.first?.id, "d1")
        XCTAssertEqual(transport.seen.first?.url, "https://example.invalid/api/v1/companies/co_1/chat?limit=1")
        XCTAssertEqual(transport.seen.first?.headers["x-api-key"], "k")
    }
